mapper.select:
select u.id, u.account_name as accountName, u.avatar_url as avatarUrl, u.preferred_locale as preferredLocale, u.status, u.created_at as createdAt, u.updated_at as updatedAt, m.id as membershipId, m.tier as membershipTier, m.status as membershipStatus, m.expires_at as membershipExpiresAt, (select count(1) from cm_profiles p join cm_profile_ownerships o on o.profile_id = p.id and o.status = 'active' where o.user_id = u.id and p.archived_at is null) as profileCount, (select count(1) from cm_profiles p join cm_profile_ownerships o on o.profile_id = p.id and o.status = 'active' where o.user_id = u.id and p.profile_type = 'self' and p.archived_at is null) as selfProfileCount, (select p.profile_status from cm_profiles p join cm_profile_ownerships o on o.profile_id = p.id and o.status = 'active' where o.user_id = u.id and p.profile_type = 'self' and p.archived_at is null order by p.updated_at desc limit 1) as selfProfileStatus from cm_users u left join cm_user_memberships m on m.id = ( select um.id from cm_user_memberships um where um.user_id = u.id order by case when um.status = 'active' and (um.expires_at is null or um.expires_at > now()) then 0 else 1 end, case when um.tier != 'free' then 0 else 1 end, case um.tier when 'diamond' then 0 when 'gold' then 1 when 'silver' then 2 when 'free' then 3 else 4 end, um.started_at desc, um.created_at desc, um.id desc limit 1 )
( u.id like concat('%', #{keyword}, '%') or u.account_name like concat('%', #{keyword}, '%') or exists ( select 1 from cm_auth_identities ai where ai.user_id = u.id and ai.identifier like concat('%', #{keyword}, '%') ) )
and u.status = #{status}
and m.tier = #{membershipTier}
and u.id in
#{userId}
and 1 = 0
and u.id not in
#{userId}
and 1 = 1
order by u.created_at desc, u.id desc
